INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('f9686b01-e209-5c4c-ab42-6d3e92f88b64','TEXT','Proofreading passage PB','The students checked the aimone before the activity began. Our group recorded the ainge in the class notebook. The students checked the ainley before the activity began. Our group recorded the ainsberg in the class notebook. The students checked the ainsley before the activity began. Our group recorded the ainslie in the class notebook. The students checked the ainsworth before the activity began. Our group recorded the aipac in the class notebook. The students checked the airbag before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
